def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_threat = 0
    urgent_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if float(opp.get('budget', 0)) > budget * 1.2:
                rich_threat += 1
            if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 4:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.6
    elif hp <= 6:
        danger += 0.25

    if no_water_days >= 2:
        danger += 1.0
    elif no_water_days == 1:
        danger += 0.55

    danger += scarcity * 0.45
    if day >= 8:
        danger += 0.15

    if hp <= 2 or no_water_days >= 2:
        bid = max(62.0, highest_prev + 2.5)
        if supply <= 17:
            bid = max(bid, 68.0)
        return float(min(budget, bid))

    if hp <= 4 or no_water_days == 1:
        if highest_prev >= 120:
            bid = 58.0 + scarcity * 10.0
        else:
            bid = max(52.0 + scarcity * 8.0, highest_prev + 2.0)
        return float(min(budget, bid))

    if highest_prev >= 130:
        bid = 16.0 + scarcity * 8.0
    elif highest_prev >= 100:
        bid = 22.0 + scarcity * 10.0
    elif highest_prev >= 70:
        bid = max(30.0 + scarcity * 8.0, avg_prev * 0.55)
    elif highest_prev > 0:
        bid = max(26.0 + scarcity * 8.0, highest_prev * 0.72)
    else:
        bid = 24.0 + scarcity * 8.0

    if rich_threat >= 2:
        bid -= 3.0
    elif urgent_opp >= 2 and supply <= 18:
        bid += 4.0

    if day >= 9 and hp >= 7 and no_water_days == 0:
        bid -= 4.0

    if bid < 8.0:
        bid = 8.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday's bids for immediate reaction
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Identify Cindy-like pressure (survivor with high bid range)
    # We don't know exact opponent logic; use yesterday trace to infer aggressor.
    aggressor_prev = 0.0
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid', None) is not None and opp.get('alive', False):
            try:
                bidv = float(prev['bid'])
            except Exception:
                bidv = 0.0
            if bidv >= highest_prev_bid * 0.85:
                aggressor_prev = max(aggressor_prev, bidv)

    # Base target based on my HP and no-water streak
    # If I'm healthy, try to bid just enough to beat weak opponents.
    # If I'm low HP or have accumulated no-water days, bid more.
    if hp <= 2.0 or no_water_days >= 2:
        urgency = 1.0
    elif hp <= 4.0 or no_water_days >= 1:
        urgency = 0.7
    else:
        urgency = 0.4

    # Supply factor: higher supply reduces need to overbid
    # supply in [15,25]
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # If Cindy (or main survivor) was bidding very high yesterday, cap our bid below that.
    # Otherwise, bid around a moderate fraction of daily salary.
    if aggressor_prev >= DAILY_SALARY * 1.2 or highest_prev_bid >= DAILY_SALARY * 1.2:
        # Aggressive opponent likely consuming water; we respond with moderate undercut.
        # Undercut by ~10-25% depending on urgency.
        undercut = 0.25 - 0.15 * urgency  # ranges ~0.10..0.25
        target = aggressor_prev * (1.0 - undercut)
        # Also ensure we don't go too low to avoid starvation
        floor_bid = DAILY_SALARY * (0.35 + 0.35 * urgency)  # ~0.35..0.70
        target = max(target, floor_bid)
    else:
        # No extreme aggressor: bid to secure water reliably
        target = DAILY_SALARY * (0.45 + 0.35 * urgency) * (0.85 + 0.15 * (1.0 - supply_norm))

    # If highest_prev_bid was moderate, slightly increase to compete
    if highest_prev_bid > 0.0 and highest_prev_bid < DAILY_SALARY * 1.2:
        target = max(target, highest_prev_bid * (0.85 + 0.1 * urgency))

    # Final clamp: cannot exceed budget; also avoid wasting when budget is low
    # Use a conservative cap to reduce variance.
    max_affordable = budget
    if budget <= 0.0:
        return 0.0

    # Don't exceed a fraction of budget unless urgency is high
    budget_cap = budget * (0.55 + 0.35 * urgency)  # ~0.55..0.90
    final_bid = min(target, budget_cap, max_affordable)

    # Ensure non-negative
    if final_bid < 0.0:
        final_bid = 0.0

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Determine urgency: need water if no_water_days > 0 or low HP
    urgent = (no_water_days > 0) or (hp <= 2)

    # Collect yesterday's bids from alive opponents
    prev_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # If no previous bids, fallback strategy
    if not prev_bids:
        if urgent:
            return min(budget, DAILY_SALARY * 0.9)
        else:
            return min(budget, DAILY_SALARY * 0.3)

    max_prev_bid = max(prev_bids)

    # Cindy-like high bidders: if max previous bid is very high (>120), avoid direct competition unless urgent
    if max_prev_bid >= 120:
        if urgent:
            # Need water badly, bid slightly higher than the high opponent
            return min(budget, max_prev_bid + 1)
        else:
            # Let them win, bid low
            return min(budget, DAILY_SALARY * 0.2)
    else:
        # Moderate bidders: outbid them by small margin if needed
        if urgent:
            target = max(max_prev_bid + 1, DAILY_SALARY * 0.5)
            return min(budget, target)
        else:
            # Not urgent, bid just above the highest previous bid to stay ahead if necessary
            return min(budget, max(max_prev_bid + 1, DAILY_SALARY * 0.3))
